'use strict';

// MODULES //

var abs = require( '@stdlib/math/base/special/abs' );


// MAIN //

/**
* Computes reciprocal Cholesky pivot growth using stored triangular columns.
*
* @private
* @param {integer} uplo - triangle enum
* @param {NonNegativeInteger} NCOLS - leading square order
* @param {Float64Array} A - original matrix
* @param {integer} sa1 - row stride of A
* @param {integer} sa2 - column stride of A
* @param {integer} oa - offset of A
* @param {Float64Array} AF - supplied factor
* @param {integer} sf1 - row stride of AF
* @param {integer} sf2 - column stride of AF
* @param {integer} of - offset of AF
* @param {Float64Array} WORK - scratch storage
* @param {NonZeroInteger} sw - scratch stride
* @param {integer} ow - scratch offset
* @returns {number} reciprocal pivot growth
*/
function base( uplo, NCOLS, A, sa1, sa2, oa, AF, sf1, sf2, of, WORK, sw, ow ) { // eslint-disable-line max-params
	var result;
	var start;
	var value;
	var index;
	var ratio;
	var denom;
	var stop;
	var i;
	var j;

	result = 1.0;
	for ( i = 0; i < 2*NCOLS; i++ ) {
		WORK[ ow+(i*sw) ] = 0.0;
	}
	for ( j = 0; j < NCOLS; j++ ) {
		start = ( uplo === 121 ) ? 0 : j;
		stop = ( uplo === 121 ) ? j+1 : NCOLS;
		index = ow + ( (NCOLS+j)*sw );
		for ( i = start; i < stop; i++ ) {
			value = abs( A[ oa+(i*sa1)+(j*sa2) ] );
			if ( value > WORK[ index ] ) {
				WORK[ index ] = value;
			}
		}
	}
	for ( j = 0; j < NCOLS; j++ ) {
		start = ( uplo === 121 ) ? 0 : j;
		stop = ( uplo === 121 ) ? j+1 : NCOLS;
		index = ow + (j*sw);
		for ( i = start; i < stop; i++ ) {
			value = abs( AF[ of+(i*sf1)+(j*sf2) ] );
			if ( value > WORK[ index ] ) {
				WORK[ index ] = value;
			}
		}
	}
	for ( j = 0; j < NCOLS; j++ ) {
		denom = WORK[ ow+(j*sw) ];
		if ( denom !== 0.0 ) {
			ratio = WORK[ ow+((NCOLS+j)*sw) ] / denom;
			if ( ratio < result ) {
				result = ratio;
			}
		}
	}
	return result;
}


// EXPORTS //

module.exports = base;
